import fs from 'node:fs';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import {createRequire} from 'node:module';
const {chromium}=createRequire(new URL('../web/package.json',import.meta.url))('playwright-core');
const dir='docs/research/photo-multisource-20261107',cache='.logs/photo-multisource-20261107',out=cache+'/live-browser',base='http://127.0.0.1:8787';fs.mkdirSync(out,{recursive:true});
const read=f=>JSON.parse(fs.readFileSync(f,'utf8')),hash=b=>crypto.createHash('sha256').update(b).digest('hex'),summary=read(dir+'/preview-coverage.json');
const files=fs.readdirSync(cache+'/preview-catalog').filter(f=>f.endsWith('.json')),expected=files.map(f=>read(cache+'/preview-catalog/'+f));
for(const file of files)assert(!read('backend/src/main/resources/catalog/'+file).places.some(p=>p.photos.some(ph=>ph.license.includes('-NC'))),'NC image leaked into distributable catalog');
const live=[];
for(const d of expected){const res=await fetch(base+'/api/catalog/destinations/'+d.id);assert.equal(res.status,200);const a=(await res.json()).destination;assert.equal(a.places.length,d.places.length);for(const p of d.places){const actual=a.places.find(x=>x.id===p.id);assert(actual);assert.equal(actual.photos.length,p.photos.length,p.name);for(let i=0;i<p.photos.length;i++)for(const key of['author','license','sourceUrl','caption','authorUrl'])assert.equal(actual.photos[i][key],p.photos[i][key]||'',p.name+' '+key);}live.push(a);}
const venues=live.flatMap(d=>d.places.filter(p=>p.venue)),urls=[...new Set(venues.flatMap(p=>p.photos.map(ph=>ph.url)))];assert.equal(venues.filter(p=>p.photos.length).length,summary.previewWithPhotos);
for(const url of urls){const res=await fetch(new URL(url,base),{signal:AbortSignal.timeout(25000)});assert.equal(res.status,200,url);const bytes=Buffer.from(await res.arrayBuffer());assert.match(res.headers.get('content-type'),/^image\/jpeg/);assert(bytes[0]===255&&bytes[1]===216);if(url.startsWith('/catalog/photos/')){const file=url.split('/').at(-1),local=file.startsWith('preview-nc-')?cache+'/preview-resources/catalog/photos/'+file:'backend/src/main/resources/catalog/photos/'+file;assert.equal(hash(bytes),hash(fs.readFileSync(local)),url);}}
const wanted=['Mì Quảng 1A','Chả Cá Thăng Long (6B Duong Thanh Street)','Bánh Xèo 46A','La Villa','Banyan Tree Lang Co Vietnam','Premier Village Phu Quoc Resort - Managed by Accor','HAIAN Beach Hotel & Spa','The Myst Dong Khoi','Cassia Cottage','Phong Nha Farmstay','Bún Chả Cá 109','Năm Đảnh','Azerai La Residence, Hue','Mango Bay Resort','Press Club','Skylight Nha Trang','Lotte Hotel Hanoi'];
const browser=await chromium.launch({channel:'chrome',headless:true}),results=[];
try{for(const width of[390,1440]){const context=await browser.newContext({viewport:{width,height:width===390?844:1000},locale:'vi-VN',reducedMotion:'reduce',isMobile:width===390,hasTouch:width===390}),page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));page.setDefaultTimeout(25000);await page.addInitScript(()=>localStorage.setItem('wander.web.onboarding.v1','{"done":true}'));
 try{for(const name of wanted){const d=live.find(d=>d.places.some(p=>p.name===name)),p=d?.places.find(p=>p.name===name);assert(p?.photos.length,name);await page.goto(base+'/?intro=0#/dest/'+d.id+'/'+p.category,{waitUntil:'domcontentloaded'});const row=page.locator('[data-place-id="'+p.id+'"]');await row.waitFor();await row.scrollIntoViewIfNeeded();await row.locator('img[data-image-ready="true"]').waitFor();await row.locator('.pr-photo').click();const dialog=page.getByRole('dialog',{name,exact:true});await dialog.waitFor();await dialog.locator('.pd-photo img[data-image-ready="true"]').waitFor();
  const linked=p.photos.findIndex(ph=>ph.authorUrl);if(linked>=0){for(let i=0;i<linked;i++)await page.keyboard.press('ArrowRight');const photo=p.photos[linked];await page.waitForFunction(url=>document.querySelector('[role="dialog"] .pd-photo img')?.getAttribute('src')===url,photo.url);const links=await dialog.locator('.pd-credit a').evaluateAll(es=>es.map(e=>e.href));assert(links.includes(photo.authorUrl),'Photographer profile attribution');assert(links.includes(photo.sourceUrl));}
  assert.deepEqual(await page.locator('#screen,[role="dialog"],.pd-credit,.pd-photo-caption').evaluateAll(es=>es.filter(e=>e.clientWidth&&e.scrollWidth>e.clientWidth+1).map(e=>e.className)),[]);await page.screenshot({path:out+'/'+width+'-'+p.id+'.png'});await dialog.getByRole('button',{name:'Đóng',exact:true}).click();}assert.deepEqual(errors,[]);results.push({width,status:'PASS',venuesChecked:wanted.length,errors});}
 catch(e){await page.screenshot({path:out+'/'+width+'-FAILED.png'});results.push({width,status:'FAIL',error:e.message,errors});}finally{await context.close();}console.log(JSON.stringify(results.at(-1)));}
}finally{await browser.close();}
const result={checkedAt:new Date().toISOString(),baseUrl:base,catalogPlaces:summary.catalogPlaces,venueCards:summary.venues,withPhotos:summary.previewWithPhotos,withoutPhotos:summary.previewWithoutPhotos,publicCatalogWithPhotos:summary.publicCatalogWithPhotos,noncommercialImagesKeptOutsidePublicResources:true,allPhotoMetadataMatches:true,uniqueImageUrlsVerified:urls.length,browser:results};fs.writeFileSync(dir+'/live-verification.json',JSON.stringify(result,null,2)+'\n');process.exitCode=results.every(r=>r.status==='PASS')?0:1;
